internal sealed class UsageNormalizingCommandApp(ICommandApp inner, TextWriter error) : ICommandApp
{
    public void Configure(Action<IConfigurator> configuration) => inner.Configure(configuration);

    public int Run(IEnumerable<string> args, CancellationToken cancellationToken = default)
    {
        var normalizedArgs = args as string[] ?? args.ToArray();
        if (IsMissingTaskSubcommand(normalizedArgs))
        {
            return WriteMissingTaskSubcommand();
        }

        return inner.Run(normalizedArgs, cancellationToken);
    }

    public Task<int> RunAsync(IEnumerable<string> args, CancellationToken cancellationToken = default)
    {
        var normalizedArgs = args as string[] ?? args.ToArray();
        if (IsMissingTaskSubcommand(normalizedArgs))
        {
            return Task.FromResult(WriteMissingTaskSubcommand());
        }

        return inner.RunAsync(normalizedArgs, cancellationToken);
    }

    private int WriteMissingTaskSubcommand()
    {
        error.WriteLine("jt task: missing subcommand. See 'jt task --help'.");
        return JobTrackCli.ExitUsage;
    }

    private static bool IsMissingTaskSubcommand(IReadOnlyList<string> args) =>
        args.Count == 1 && string.Equals(args[0], "task", StringComparison.Ordinal);
}

