    private static readonly string[] TaskObjectPropertyNames = ["task", "data", "item"];
    private static readonly string[] ShortCodePropertyNames = ["shortCode", "short_code", "code", "id"];
    private static readonly string[] TitlePropertyNames = ["title", "name"];
    private static readonly string[] StatusPropertyNames = ["status", "state"];
    private static readonly string[] ProjectPropertyNames = ["projectId", "project", "project_id"];

    public static IReadOnlyList<TaskRow>? ReadTaskRows(string raw)
    {
        using var doc = TryParse(raw);
        if (doc is null)
        {
            return null;
        }

        var source = TaskArrayOrNull(doc.RootElement);
        if (source is null)
        {
            return null;
        }

        var rows = new List<TaskRow>();
        foreach (var item in source.Value.EnumerateArray())
        {
            var row = ReadTaskRowOrNull(item);
            if (row is null)
            {
                return null;
            }

            rows.Add(row);
        }

        return rows;
    }

    public static IReadOnlyList<TaskDetail>? ReadTaskDetails(string raw)
    {
        using var doc = TryParse(raw);
        if (doc is null)
        {
            return null;
        }

        var task = TaskObjectOrNull(doc.RootElement);
        if (task is null)
        {
            return null;
        }

        var details = new List<TaskDetail>();
        AddIfPresent(details, "Short code", ReadString(task.Value, ShortCodePropertyNames));
        AddIfPresent(details, "Title", ReadString(task.Value, TitlePropertyNames));
        AddIfPresent(details, "Status", ReadString(task.Value, StatusPropertyNames));
        AddIfPresent(details, "Project", ReadString(task.Value, ProjectPropertyNames));
        AddIfPresent(details, "Description", ReadString(task.Value, "description"));
        return details.Count == 0 ? null : details;
    }

    private static JsonDocument? TryParse(string raw)
    {
        try
        {
            return JsonDocument.Parse(raw);
        }
        catch (JsonException)
        {
            return null;
        }
    }

    private static JsonElement? TaskArrayOrNull(JsonElement root)
    {
        if (root.ValueKind == JsonValueKind.Array)
        {
            return root;
        }

        if (root.ValueKind != JsonValueKind.Object)
        {
            return null;
        }

        foreach (var propertyName in TaskArrayPropertyNames)
        {
            if (root.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.Array)
            {
                return property;
            }
        }

        return null;
    }

    private static TaskRow? ReadTaskRowOrNull(JsonElement item)
    {
        var shortCode = ReadString(item, ShortCodePropertyNames);
        var title = ReadString(item, TitlePropertyNames);
        var status = ReadString(item, StatusPropertyNames);
        return string.IsNullOrEmpty(shortCode) && string.IsNullOrEmpty(title) && string.IsNullOrEmpty(status)
            ? null
            : new TaskRow(shortCode, title, status);
    }

    private static JsonElement? TaskObjectOrNull(JsonElement root)
    {
        if (root.ValueKind == JsonValueKind.Object)
        {
            foreach (var propertyName in TaskObjectPropertyNames)
            {
                if (root.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.Object)
                {
                    return property;
                }
            }

            return root;
        }

        return null;
    }

